import { OrderRepository } from "../domain/order-repository";
import { ProductRepository } from "../domain/product-repository";
import { releaseStock } from "../domain/stock-reservation";
import { OrderDto, toOrderDto } from "./order-dto";
import { requireOrder } from "./require-order";

export class CancelOrderUseCase {
  constructor(
    private readonly orders: OrderRepository,
    private readonly products: ProductRepository,
  ) {}

  async execute(orderId: string): Promise<OrderDto> {
    const order = await requireOrder(this.orders, orderId);
    order.cancel();

    const found = await this.products.findByIds(order.lines.map((line) => line.productId));
    releaseStock(new Map(found.map((product) => [product.id, product])), order.lines);
    for (const product of found) {
      await this.products.save(product);
    }
    await this.orders.save(order);
    return toOrderDto(order);
  }
}

